/* Countdown theme refinement: restrained motion, navy and gold throughout */
.top-area{position:relative;isolation:isolate;overflow:hidden;margin:0 -18px;padding:calc(env(safe-area-inset-top) + 17px) 18px 17px;background:radial-gradient(ellipse at 88% 2%,#d4af3725,transparent 34%),linear-gradient(140deg,#0b1d39 0%,#19375f 56%,#10294b 100%)!important;border:0;border-bottom:1px solid #c6a348;border-radius:0 0 24px 24px;color:#fff;box-shadow:0 12px 26px #10294b20}
