.top-area:after{content:"";position:absolute;z-index:-1;right:5%;bottom:14px;width:90px;height:58px;border:1px solid #d4af3725;border-radius:50%;transform:rotate(-24deg);pointer-events:none}
.topline{overflow:visible;margin:0 2px;padding:2px 0 0;border:0;border-radius:0;background:transparent;box-shadow:none}
.brandcopy strong,.brandcopy .brand-star{color:#f0d98b;text-shadow:none;animation:none!important}
.brandcopy span:not(.brand-star){color:#dce4ef;font-weight:600}
.menu-toggle,.bell{color:#f0d98b}
.menu-toggle{border-color:#d4af376b;background:#ffffff0b}
.menu-toggle span{background:#f0d98b}
.avatar{border:1.5px solid #d4af37;background:linear-gradient(145deg,#fff,#e9edf5);box-shadow:0 2px 10px #0003;animation:none!important}
.bell i{animation:none!important}
.creator-card{margin-top:24px;padding:17px;border:1px solid #d4af37;border-radius:22px;background:radial-gradient(ellipse at 100% 0%,#d4af3718,transparent 38%),linear-gradient(145deg,#0b1d39,#19375f 56%,#10294b);background-size:auto;color:#fff;box-shadow:0 12px 26px #10294b20,inset 0 1px 0 #ffffff20;animation:none!important}
.creator-card:before{inset:6px;border:1px solid #d4af3738;border-radius:16px}
.creator-heading{border-bottom-color:#d4af3744}
