.creator-link:after{display:none}
/* Continuous decorative effects are removed; only countdown digit changes animate. */
*,*:before,*:after{animation:none!important}
.countdown-num.tick{animation:digitRoll .35s cubic-bezier(.2,.8,.25,1)!important}
.motion-in,.motion-in.motion-visible,.study-heading.motion-in,.schedule-heading.motion-in{opacity:1;transform:none;filter:none;transition:none}
@media(prefers-reduced-motion:reduce){.countdown-num.tick{animation:none!important}}
/* Keep the footer motto legible below the creator card */
.footer{font-size:9px;letter-spacing:.035em;line-height:1.55;color:#7b8798}








