.askai-page .profile-page-head{flex:none!important;min-height:78px!important;align-items:center!important;gap:12px!important;margin:0!important;padding:15px 18px 13px!important;border:0!important;border-bottom:1px solid #d4af376c!important;background:linear-gradient(120deg,#10294b,#17375f 72%,#1b3d68)!important;box-shadow:0 5px 18px #10294b20!important}
.askai-page .profile-page-head>div{min-width:0}
.askai-page .profile-page-kicker{color:#e4cb78!important;font-size:8px!important;letter-spacing:.17em!important}
.askai-page .profile-page-head h2{margin-top:5px!important;color:#fff!important;font:700 22px/1.1 var(--serif)!important;letter-spacing:.015em!important}
.askai-page .profile-page-close{flex:none!important;width:auto!important;height:35px!important;padding:0 12px!important;border:1px solid #d9bd68!important;border-radius:999px!important;background:linear-gradient(135deg,#fff4cf,#d8b85e)!important;color:#10294b!important;font-size:11px!important;font-weight:800!important;box-shadow:0 4px 11px #07172e40!important}
.askai-welcome{flex:none!important;position:relative!important;overflow:hidden!important;gap:12px!important;margin:14px 14px 10px!important;padding:14px!important;border:1px solid #c5a34b!important;border-radius:18px!important;background:radial-gradient(ellipse at 100% 0%,#d5b34b26,transparent 48%),linear-gradient(125deg,#10294b,#193b65)!important;color:#fff!important;box-shadow:0 9px 20px #10294b20,inset 0 1px 0 #ffffff20!important}
.askai-welcome:after{content:"";position:absolute;right:-34px;bottom:-66px;width:130px;height:130px;border:1px solid #e2c86b38;border-radius:50%;box-shadow:0 0 0 12px #e2c86b0b,0 0 0 25px #e2c86b08;pointer-events:none}
.askai-mark{position:relative!important;z-index:1!important;width:42px!important;height:42px!important;border:1px solid #f2dc94!important;border-radius:14px!important;background:linear-gradient(145deg,#fff0b8,#c5a04a)!important;color:#10294b!important;font-size:22px!important;box-shadow:0 5px 12px #06132966,inset 0 1px 0 #fff!important}
.askai-welcome>div:last-child{position:relative;z-index:1;min-width:0}
.askai-welcome h3{color:#f1dfa2!important;font:700 15px/1.2 var(--serif)!important}
.askai-welcome p{max-width:38em;margin-top:5px!important;color:#e4eaf2!important;font-size:10px!important;font-weight:600!important;line-height:1.45!important}
.askai-status{flex:none!important;align-self:flex-start!important;margin:0 16px 9px!important;padding:6px 10px!important;border:1px solid #d7c47f!important;border-radius:999px!important;background:#fffdf7!important;color:#6e5925!important;font-size:9px!important;font-weight:750!important;box-shadow:0 3px 9px #10294b0a!important}
.askai-status:before{content:"";display:inline-block;width:6px;height:6px;margin:0 7px 1px 0;border-radius:50%;background:#b59132;box-shadow:0 0 0 3px #d4af3724;vertical-align:middle}
.askai-status.error{border-color:#dfb5a9!important;background:#fff8f5!important;color:#8d4539!important}
.askai-messages{flex:1 1 auto!important;min-height:0!important;gap:11px!important;overflow-x:hidden!important;padding:13px 14px 15px!important;background:radial-gradient(ellipse at 0% 100%,#d4af3710,transparent 35%),linear-gradient(180deg,#f7f8fb,#f2f5f9)!important;scrollbar-width:thin!important;scrollbar-color:#c6aa5b transparent!important}
.askai-intro{max-width:88%!important;align-self:flex-start!important;padding:12px 14px!important;border:1px solid #dfd3ab!important;border-radius:5px 17px 17px 17px!important;background:linear-gradient(145deg,#fffefa,#f8f5eb)!important;color:#344864!important;font-size:11px!important;font-weight:600!important;line-height:1.55!important;box-shadow:0 5px 14px #10294b0b!important}
.askai-message{max-width:88%!important;padding:12px 14px!important;border:1px solid #dfe4ec!important;border-radius:5px 17px 17px 17px!important;background:#fff!important;color:#213954!important;font-size:12px!important;font-weight:600!important;line-height:1.6!important;box-shadow:0 5px 15px #10294b0d!important;animation:askMessageIn .24s ease-out both!important}
.askai-message.user{align-self:flex-end!important;border-color:#d5ba65!important;border-radius:17px 5px 17px 17px!important;background:linear-gradient(135deg,#fff4ce,#ecd58a)!important;color:#10294b!important;box-shadow:0 5px 14px #92702c1c,inset 0 1px 0 #fff9!important}
.askai-message.assistant{align-self:flex-start!important}
.askai-sources{gap:6px!important;margin-top:10px!important;padding-top:9px!important;border-top:1px solid #e9e4d7!important}
.askai-source{padding:5px 8px!important;border:1px solid #d8c47e!important;border-radius:999px!important;background:#fbf8ed!important;color:#665321!important;font-size:9px!important;font-weight:750!important}
.askai-contact{flex-wrap:wrap!important;gap:8px!important;margin-top:11px!important}
.askai-contact a{min-height:36px!important;padding:0 13px!important;border:1px solid #d9c47a!important;border-radius:999px!important;background:linear-gradient(120deg,#fff2c6,#d9b95f)!important;color:#10294b!important;font-size:10px!important;font-weight:800!important;box-shadow:0 4px 9px #10294b14!important}
.askai-form{flex:none!important;align-items:flex-end!important;gap:8px!important;margin:10px 13px 8px!important;padding:7px!important;border:1px solid #c9ab58!important;border-radius:19px!important;background:#fff!important;box-shadow:0 7px 19px #10294b16,inset 0 1px 0 #fff!important}
.askai-form:focus-within{border-color:#b28c31!important;box-shadow:0 0 0 3px #d4af3724,0 7px 19px #10294b16!important}
.askai-form textarea{min-height:43px!important;max-height:112px!important;padding:10px 11px!important;color:#173456!important;font:600 12px/1.45 var(--sans)!important}
.askai-form textarea::placeholder{color:#77859a!important;font-weight:550!important}
.askai-form button{width:43px!important;height:43px!important;flex:none!important;border:1px solid #e6cf83!important;border-radius:15px!important;background:linear-gradient(140deg,#f5e6b0,#c19a43)!important;color:#10294b!important;font-size:19px!important;box-shadow:0 4px 9px #10294b20,inset 0 1px 0 #fff9!important;transition:transform .18s ease,filter .18s ease!important}
.askai-form button:active{transform:scale(.94)!important}
.askai-form button:disabled{opacity:.55!important}
.askai-disclaimer{flex:none!important;margin:0 18px 2px!important;color:#64738a!important;font-size:9px!important;font-weight:650!important;line-height:1.4!important;text-align:center!important}
@keyframes askMessageIn{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:360px){.askai-page .profile-page-head{min-height:72px!important;padding-left:14px!important;padding-right:14px!important}.askai-page .profile-page-head h2{font-size:20px!important}.askai-welcome{margin:11px 11px 8px!important;padding:12px!important}.askai-welcome p{font-size:9px!important}.askai-messages{padding-left:11px!important;padding-right:11px!important}.askai-message,.askai-intro{max-width:92%!important;font-size:11px!important}.askai-form{margin-left:10px!important;margin-right:10px!important}}
@media(prefers-reduced-motion:reduce){.askai-message{animation:none!important}.askai-form button{transition:none!important}}
/* Branded contact actions and in-app preview sheet. */
.askai-contact{display:grid!important;grid-template-columns:1fr 1fr!important;gap:8px!important}
.contact-preview-trigger{display:grid!important;grid-template-columns:34px minmax(0,1fr) 16px!important;align-items:center!important;gap:8px!important;min-width:0!important;min-height:54px!important;padding:7px 9px!important;border:1px solid #d8c47e!important;border-radius:14px!important;background:linear-gradient(145deg,#fffefa,#f4f2e9)!important;color:#142e50!important;text-align:left!important;box-shadow:0 4px 11px #10294b13,inset 0 1px 0 #fff!important;cursor:pointer!important;transition:transform .18s ease,box-shadow .18s ease!important}
.contact-preview-trigger:active{transform:scale(.97)!important;box-shadow:0 2px 6px #10294b18!important}
.contact-brand-icon{width:34px!important;height:34px!important;display:grid!important;place-items:center!important;border:1px solid #e4d396!important;border-radius:11px!important;background:linear-gradient(145deg,#18375d,#10294b)!important;color:#f1d987!important}
.contact-brand-icon svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.contact-preview-trigger>span:nth-child(2){display:grid!important;gap:3px!important;min-width:0!important}
.contact-preview-trigger strong{color:#173354!important;font-size:10px!important;font-weight:850!important;line-height:1.1!important}
.contact-preview-trigger small{color:#77849a!important;font-size:8px!important;font-weight:700!important;line-height:1.1!important}
.contact-preview-arrow{color:#a27d2e!important;font-size:19px!important;font-weight:800!important;text-align:center!important}
.contact-preview{position:fixed!important;z-index:120!important;inset:0!important;display:grid!important;place-items:end center!important;padding:16px!important}
.contact-preview[hidden]{display:none!important}
.contact-preview-scrim{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;border:0!important;background:#06152bd1!important;backdrop-filter:blur(7px)!important;cursor:pointer!important}
.contact-preview-card{position:relative!important;z-index:1!important;width:min(100%,410px)!important;padding:10px 18px calc(18px + env(safe-area-inset-bottom))!important;border:1px solid #d4af37!important;border-radius:24px!important;background:linear-gradient(165deg,#fffefa,#f2f5f9)!important;color:#142e50!important;box-shadow:0 18px 50px #020a1c70,inset 0 1px 0 #fff!important;animation:contactPreviewIn .22s ease-out both!important}
.contact-preview-grabber{width:38px;height:4px;margin:0 auto 15px;border-radius:99px;background:#b9a25d80}
.contact-preview-kicker{color:#96752c;font-size:8px;font-weight:850;letter-spacing:.18em;text-align:center}
.contact-preview-platform{width:max-content;max-width:100%;margin:11px auto 14px;padding:6px 10px;border:1px solid #d7c37e;border-radius:999px;background:#fbf7e9;color:#6d5723;font-size:9px;font-weight:800}
.contact-preview-platform.whatsapp{background:#eef5e9;color:#3d644a;border-color:#b9d1b3}
.contact-preview-platform.instagram{background:#f6eff1;color:#76505d;border-color:#dec3c7}
.contact-preview-person{display:flex;align-items:center;gap:13px;padding:14px;border:1px solid #d9c787;border-radius:18px;background:radial-gradient(circle at 100% 0%,#d4af371a,transparent 45%),linear-gradient(130deg,#10294b,#193b65);box-shadow:0 8px 18px #10294b20}
.contact-preview-person img{width:58px;height:58px;flex:none;object-fit:cover;object-position:center 34%;border:2px solid #dfc875;border-radius:17px;box-shadow:0 4px 10px #06132970}
.contact-preview-person h3{margin:0;color:#f2dfa0;font:700 17px/1.2 var(--serif)}
.contact-preview-person p{margin:5px 0 0;color:#fff;font-size:11px;font-weight:750;letter-spacing:.02em}
.contact-preview-note{margin:13px 2px 16px;color:#4d5f77;font-size:11px;font-weight:600;line-height:1.55;text-align:center}
.contact-preview-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.contact-preview-actions button,.contact-preview-actions a{min-height:43px;display:flex;align-items:center;justify-content:center;padding:0 11px;border:1px solid #d2bd79;border-radius:999px;background:linear-gradient(145deg,#fffefa,#f0f2f6);color:#17365d;text-decoration:none;font:800 10px var(--sans);box-shadow:0 4px 10px #10294b12;cursor:pointer}
