@keyframes contactPreviewIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:360px){.askai-contact{gap:6px!important}.contact-preview-trigger{grid-template-columns:30px minmax(0,1fr) 12px!important;gap:6px!important;min-height:50px!important;padding:6px!important}.contact-brand-icon{width:30px!important;height:30px!important}.contact-preview-card{padding-left:14px!important;padding-right:14px!important}}
@media(prefers-reduced-motion:reduce){.contact-preview-card{animation:none!important}.contact-preview-trigger{transition:none!important}}









/* Creator card echoes the exam countdown's navy chronograph frame. */
