#scholarshipDetailsPage .scholarship-detail-panel{position:relative;width:min(100%,820px);height:100dvh;max-height:100dvh;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding:calc(env(safe-area-inset-top) + 18px) 22px calc(env(safe-area-inset-bottom) + 26px);background:radial-gradient(ellipse at 100% 0%,rgba(222,196,133,.2),transparent 30%),linear-gradient(155deg,#fffdf7 0%,#f8f3e8 54%,#f0ebdf 100%);box-shadow:0 0 60px rgba(0,0,0,.3);transform:translateY(14px);transition:transform .3s var(--ease-premium)}
