#scholarshipDetailsPage #scholarshipDetailsTitle{margin:0;color:#fff9e9;font:600 clamp(25px,5vw,32px)/1.12 var(--serif);letter-spacing:-.02em;text-shadow:0 2px 4px rgba(0,0,0,.3)}
#scholarshipDetailsPage .scholarship-detail-subtitle{margin:7px 0 0;color:#e4eaf1;font:450 13px/1.45 var(--sans)}
#scholarshipDetailsPage .scholarship-detail-close{position:relative;z-index:1;display:grid;place-items:center;flex:0 0 42px;width:42px;height:42px;border:1px solid #edda9c;border-radius:12px 4px 12px 4px;background:linear-gradient(145deg,#f6e5ae,#d3b15b 70%,#bd9340);color:#172f4b;font:500 23px/1 var(--sans);box-shadow:inset 0 1px 0 rgba(255,255,255,.75),0 2px 0 #8e6b2b,0 5px 10px rgba(0,0,0,.22);cursor:pointer;transition:background .2s var(--ease-premium),transform .2s var(--ease-premium),box-shadow .2s var(--ease-premium)}
