#scholarshipDetailsPage .scholarship-detail-hero{position:relative;isolation:isolate;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:20px;margin:0 0 16px;padding:20px 21px;overflow:hidden;border:1px solid #b68d3e;border-radius:17px 5px 17px 5px;background:radial-gradient(ellipse at 95% 0%,rgba(255,255,255,.68),transparent 42%),radial-gradient(ellipse at 0% 100%,rgba(207,171,91,.16),transparent 38%),radial-gradient(circle at 1px 1px,rgba(116,82,26,.045) .5px,transparent .9px) 0 0/8px 8px,linear-gradient(135deg,#fffdf7,#f7ecd5 58%,#f0e1c2);box-shadow:0 10px 22px rgba(70,51,19,.14),inset 0 1px 0 rgba(255,255,255,.82),inset 0 -4px 10px rgba(139,99,31,.09)}
#scholarshipDetailsPage .scholarship-detail-hero:before{content:"";position:absolute;z-index:0;inset:4px;border:1px solid rgba(168,127,47,.28);border-radius:12px 2px 12px 2px;box-shadow:inset 0 1px 0 rgba(255,255,255,.45);pointer-events:none}
