#scholarshipDetailsPage .scholarship-detail-portal-link{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-width:166px;min-height:44px;padding:9px 12px 9px 15px;border:1px solid #a77e2d;border-radius:11px 4px 11px 4px;background:linear-gradient(135deg,#fff0b8 0%,#e6c666 42%,#c99d3f 100%);color:#182f49;font:750 12px/1.2 var(--sans);text-align:center;text-decoration:none;box-shadow:inset 0 1px 0 rgba(255,255,255,.92),inset 0 -3px 4px rgba(102,70,15,.15),0 2px 0 #906b25,0 5px 9px rgba(74,54,19,.17);transition:background .2s var(--ease-premium),box-shadow .2s var(--ease-premium),transform .2s var(--ease-premium)}
